// job_id en query, sans valeur par défaut : interroger un job arbitraire
// exposerait le travail d'un autre utilisateur.
const input = $input.first().json;
const query = input.query || {};
const jobId = query.job_id;

if (!jobId || typeof jobId !== 'string') {
  return [{
    json: {
      valide: false,
      erreur: { code: 400, message: 'Le paramètre "job_id" est requis', status: 'BAD_REQUEST' }
    }
  }];
}

return [{ json: { valide: true, jobId: jobId } }];

// Le registre /api/v2/jobs porte le statut et la progression, jamais le texte.
// Quand le job est terminé, il faut donc aller chercher le résultat ailleurs.
const input = $input.first().json;
const jobId = $('Lire Paramètres').first().json.jobId;

// Avec onError continueRegularOutput, un HTTP Request en échec ne produit PAS
// {statusCode, body} : statusCode est absent, et le statut réel est enfoui dans
// le message sous la forme « 404 - {...} ». Sans cette lecture, un job inconnu
// ressortait en HTTP 200 avec JOB_NOT_FOUND dans le corps — MCP relaie
// fidèlement le statut, il aurait donc relayé un succès. Même parade que #422.
let code = input.statusCode;
if (code === undefined) {
  const brut = String(input?.error?.message || input?.message || '');
  const m = brut.match(/^\s*(\d{3})\s*-\s*/);
  code = m ? parseInt(m[1], 10) : (input?.error ? 502 : 200);
}
const data = input.body || input;

if (code >= 400 || !data || data.error) {
  return [{
    json: {
      success: false,
      job_id: jobId,
      error: {
        code: code,
        message: data?.error?.message || data?.message || 'Job introuvable',
        status: 'JOB_NOT_FOUND'
      },
      _chercherResultat: false
    }
  }];
}

return [{
  json: {
    ...data,
    job_id: data.job_id || data.id || jobId,
    jobId: jobId,
    _chercherResultat: data.status === 'completed'
  }
}];

// Assemble statut + texte. Trois issues possibles, toutes explicites :
//
//   completed + résultat présent  → success, le texte est là
//   completed + résultat absent   → ANOMALIE (result_missing) : le job dit
//                                   « terminé » mais le texte a disparu ou n'a
//                                   jamais été déposé. Signalé, jamais masqué —
//                                   c'est ce qui empêche chat.api de facturer
//                                   une traduction perdue (azy.daily#194).
//   dépôt illisible               → remonté tel quel
//
// Le modèle Torah masque le 2e cas (Fetch Result en continueRegularOutput) : il
// y est sans conséquence, le plugin rechargeant la page depuis la base. Ici il
// n'existe aucune base où retomber.
const statut = $('Examiner Statut').first().json;
const brut = $input.first().json;
const reponse = brut.body || brut;
const code = brut.statusCode || 200;

const base = {
  job_id: statut.job_id,
  status: statut.status,
  progress: statut.progress || null,
  output: statut.output || null
};

if (code >= 400 || reponse.success === false) {
  return [{
    json: {
      ...base,
      success: false,
      result: null,
      error: {
        code: 502,
        message: 'Dépôt de résultat injoignable ou illisible',
        status: 'RESULT_STORE_ERROR'
      }
    }
  }];
}

if (!reponse.found || !reponse.result) {
  return [{
    json: {
      ...base,
      success: false,
      result: null,
      error: {
        code: 410,
        message: 'Job terminé mais résultat absent : jamais déposé, ou fenêtre de 1 h dépassée. Ne pas facturer.',
        status: 'RESULT_MISSING'
      }
    }
  }];
}

return [{
  json: {
    ...base,
    success: true,
    stored_at: reponse.stored_at,
    result: reponse.result
  }
}];

// Job non terminé : statut et progression suffisent, il n'y a rien à chercher.
const j = $input.first().json;
return [{
  json: {
    success: j.success !== false,
    job_id: j.job_id,
    status: j.status || null,
    progress: j.progress || null,
    result: null,
    error: j.error || null
  }
}];
